export function drawAttackDetail(c,e,t){const alpha=Math.max(0,1-t);if(e.kind==='recall'){c.globalAlpha=alpha*.7;c.fillStyle=e.color;for(let i=0;i<10;i++){const a=i*Math.PI/5,r=24*(1-t);c.fillRect(e.to.x+Math.cos(a)*r,e.to.y-12+Math.sin(a)*r-t*18,2,2)}return true}if(e.kind==='fissure'){const progress=Math.min(1,t*1.8),n=20;c.lineWidth=4;c.strokeStyle='#201a25';c.beginPath();c.moveTo(e.from.x,e.from.y+24);for(let i=1;i<=Math.floor(n*progress);i++){const q=i/n;c.lineTo(e.from.x+(e.to.x-e.from.x)*q+Math.sin(i*3.1)*9,e.from.y+24+(e.to.y-e.from.y)*q)}c.stroke();c.lineWidth=1;c.strokeStyle=e.color;c.stroke();return true}
 if(e.kind==='splash'){for(let i=0;i<14;i++){const a=i*Math.PI/7,v=35+(i%4)*10,x=e.to.x+Math.cos(a)*v*t,y=e.to.y+18-Math.sin(Math.PI*t)*35+Math.sin(a)*v*t*.45;c.fillStyle=i%2?'#c9f5ff':e.color;c.globalAlpha=alpha;c.fillRect(x,y,3,5)}c.lineWidth=2;c.strokeStyle=e.color;c.beginPath();c.ellipse(e.to.x,e.to.y+28,8+t*60,3+t*17,0,0,Math.PI*2);c.stroke();return true}
 if(e.kind==='ice-shards'){for(let i=0;i<8;i++){const a=i*Math.PI/4,x=e.to.x+Math.cos(a)*t*55,y=e.to.y+10+Math.sin(a)*t*20-Math.sin(Math.PI*t)*22;c.globalAlpha=alpha;c.fillStyle=i%2?'#efffff':e.color;c.beginPath();c.moveTo(x,y-7);c.lineTo(x+3,y);c.lineTo(x,y+7);c.lineTo(x-3,y);c.closePath();c.fill()}return true}
 if(e.kind==='smoke'){for(let i=0;i<6;i++){c.globalAlpha=alpha*.22;c.fillStyle='#c2b5a6';const size=8+t*18+i;c.fillRect(e.to.x+Math.sin(i*3)*18-t*10,e.to.y+20-t*(35+i*4),size,size)}return true}return false}
